use allowit::prelude::*;
/// Pay only recipients I approve.
pub fn execute(ctx: &AllowitContext) -> allowit::Result {
    allowit::recipients(ctx, ctx.params.get(allowit::RECIPIENTS))?;
    Ok(())
}

